import numpy as npimport matplotlib.pyplot as pltv1 = np.array(list(map(float, input("Enter v1: ").split())))v2 = np.array(list(map(float, input("Enter v2: ").split())))v3 = np.array(list(map(float, input("Enter v3: ").split())))# Gram-Schmidt Orthogonalizationu1 = v1p_v2_u1 = (np.dot(v2,u1)/np.dot(u1,u1))*u1u2 = v2- p_v2_u1p_v3_u1 = (np.dot(v3,u1)/np.dot(u1, u1))*u1p_v3_u2 = (np.dot(v3,u2)/np.dot(u2, u2))*u2u3 = v3 -p_v3_u1-p_v3_u2#normalize e1 = u1/np.linalg.norm(u1)e2 = u2/np.linalg.norm(u2)e3 = u3/np.linalg.norm(u3)#resultsprint("\nOrthogonal vectors:")print("u1 =", u1)print("u2 =", u2)print("u3 =", u3)print("\nOrthonormal vectors:")print("e1 =", e1)print("e2 =", e2)print("e3 =", e3)fig = plt.figure()ax = fig.add_subplot(111, projection='3d')origin = np.zeros(3)# Orthogonal vectorsax.quiver(*origin, *u1, linestyle='--', label="u1")ax.quiver(*origin, *u2, linestyle='--', label="u2")ax.quiver(*origin, *u3, linestyle='--', label="u3")# Orthonormal vectorsax.quiver(*origin, *e1, label="e1")ax.quiver(*origin, *e2, label="e2")ax.quiver(*origin, *e3, label="e3")ax.set_xlabel("X")ax.set_ylabel("Y")ax.set_zlabel("Z")ax.set_title("Gram-Schmidt Orthogonalization")ax.legend()plt.show()